INSERT INTO publications (title, authors, year, abstract_text, doi, url) SELECT 'DSSA (Domain-Specific Software Architecture)', 'Will Tracz', 1995, '<jats:p>A Domain-Specific Software Architecture (DSSA) has been defined as:&amp;bull; "an assemblage of software components, specialized for a particular type of task (domain), generalized for effective use across that domain, composed in a standardized structure (topology) effective for building successful applications" [Hay94] or, alternately&amp;bull; "a context for patterns of problem elements, solution elements, and situations that define mappings between them [Hid90].The following small example illustrates these definitions as well as provides the reader with some insight into the types of processes and tools needed to support the creation and use of a DSSA.</jats:p>', '10.1145/219308.219318', 'https://doi.org/10.1145/219308.219318' WHERE NOT EXISTS (SELECT 1 FROM publications WHERE doi = '10.1145/219308.219318');
