INSERT INTO publications (title, authors, year, abstract_text, doi, url) SELECT 'Eksplorasi Software CBE Thermal Comfort Tool Sebagai Perhitungan Kenyamanan Termal', 'Calvindoro Mamesa; LMF Purwanto', 2022, '<jats:p>Dalam menjalankan aktivitas dalam sebuah ruangan, tentunya setiap orang berharap ruang yang digunakannya nyaman secara termal. Bangunan dengan fungsi peribadatan tentunya menuntut akan tercapainya kenyamanan termal salah satunya adalah bangunan Gereja dimana kenyamanan termal akan berpengaruh terhadap fokus umatnya dalam mengikuti peribadatan di dalam Gereja. Gereja Gedangan adalah salah satu Gereja di Semarang yang memiliki banyak bukaan lebar guna masuknya penghawaan alami kedalam bangunan sehingga bangunan ini cukup menarik untuk dijadikan penelitian mengenai kenyamanan termal. Dewasa ini, perhitungan kenyamanan termal sendiri sudah banyak dilakukan dan seiring berjalannya waktu, teknologi memberi kemudahan kepada manusia dalam melakukan perhitungan kenyamanan termal terutama dalam menemukan nilai PMV dan PPD karena perhitungan ini cukup rumit tanpa bantuan software. Penelitian ini menggunakan metode eksperimen yaitu dengan cara mengumpulkan data yang berupa angka melalui pengukuran di lapangan kemudian akan dihitung dan dianalisis dengan CBE Thermal Comfort Tool dan jika belum tercapai kenyamanan termal maka dilakukan eksperimen agar kenyamanan termal dapat tercapai. Penelitian mengenai kenyamanan termal pada bangunan fungsi peribadatan sangat penting untuk mengetahui apakah bangunan tersebut memenuhi kenyamanan termal pengguna dan jika belum, maka bagaimanakah solusi yang dapat diambil untuk dapat mencapai kenyamanan termal tersebut. Hasil yang akan dicapai dari penelitian ini adalah mengetahui nilai PMV dan PPD pada Gereja Gedangan dan solusi yang dapat diterapkan apabila kenyamanan termal pada Gereja Gedangan belum tercapai. </jats:p>', '10.24167/joda.v1i2.4305', 'https://doi.org/10.24167/joda.v1i2.4305' WHERE NOT EXISTS (SELECT 1 FROM publications WHERE doi = '10.24167/joda.v1i2.4305');
