INSERT INTO publications (title, authors, year, abstract_text, doi, url) SELECT 'Towards software architecture at runtime', 'Gang Huang; Hong Mei; Qian-xiang Wang', 2003, '<jats:p>As Internet and wireless network make the runtime environment much more dynamic and open, software becomes more and more complex and difficult to maintain. Software architecture at run-time (RSA) can help maintainers understand and reason the run-time system. Moreover, RSA helps to keep SA consistent in the whole software lifecycle. This paper presents an approach to three fundamental issues of RSA, including making RSA the first-class entity at runtime, maintaining the causal-connection between RSA and the runtime system, and mapping RSA from/into SA at the design phase.</jats:p>', '10.1145/638750.638780', 'https://doi.org/10.1145/638750.638780' WHERE NOT EXISTS (SELECT 1 FROM publications WHERE doi = '10.1145/638750.638780');
