INSERT INTO publications (title, authors, year, abstract_text, doi, url) SELECT 'PEMANFAATAN SOFTWARE ROBOT STRUCTURAL ANALYSIS UNTUK MENGOPTIMALKAN DESAIN STRUKTUR KAYU', 'Sulistyorini Sulistyorini, F; Rudyto Rudyto, B', 2024, '<jats:p>Konstruksi kayu telah menjadi pilihan material ramah lingkungan dan berkelanjutan dalam pembangunan modern. Namun, tantangan dalam mengoptimalkan desain struktur kayu meliputi pengendalian stabilitas dan ketahanan terhadap beban yang kompleks. Penelitian ini bertujuan untuk mengaplikasikan software Robot Structural Analysis dalam proses desain struktur kayu, dengan fokus pada peningkatan efisiensi struktural dan optimalisasi penggunaan material. Metode penelitian melibatkan pemodelan struktur kayu dengan berbagai skenario beban, termasuk beban angin, gempa, dan beban hidup, yang disimulasikan menggunakan Robot Structural Analysis. Setiap skenario dianalisis untuk mengevaluasi distribusi tegangan, deformasi, dan faktor keamanan struktur kayu. Hasil penelitian menunjukkan bahwa dengan menggunakan Robot Structural Analysis, desain struktur kayu dapat dioptimalkan dengan lebih presisi, yang terbukti dari penurunan penggunaan material hingga 15% tanpa mengorbankan keamanan struktural. Selain itu, metode simulasi ini mempercepat proses desain dengan memberikan solusi visualisasi terhadap potensi kerusakan dan titik lemah struktur. Penelitian ini menunjukkan bahwa pemanfaatan teknologi digital, khususnya software Robot Structural Analysis, efektif dalam meningkatkan efisiensi dan keamanan desain konstruksi kayu di berbagai kondisi lingkungan.</jats:p>', '10.24167/joda.v3i2.12674', 'https://doi.org/10.24167/joda.v3i2.12674' WHERE NOT EXISTS (SELECT 1 FROM publications WHERE doi = '10.24167/joda.v3i2.12674');
