INSERT INTO publications (title, authors, year, abstract_text, doi, url) SELECT 'A software architecture for cell manipulation', 'Mahdi Azizian; Rajni Patel; Cezar Gavrilovici; Michael Poulter', 2011, '<jats:p>A software architecture has been developed for image-guided robot-assisted cell manipulation. The system provides tools for positioning and navigation of multiple micromanipulators under live microscope images. The main application of this system is in multi-electrode patch clamp electrophysiology; however the same architecture can be used for any other type of cell micromanipulation as well as other applications such as micro-assembly.</jats:p>', '10.54294/3moo86', 'https://doi.org/10.54294/3moo86' WHERE NOT EXISTS (SELECT 1 FROM publications WHERE doi = '10.54294/3moo86');
