INSERT INTO publications (title, authors, year, abstract_text, doi, url) SELECT 'Software Information Management-Oriented Software Architecture Analysis', 'Liang Xiang; Yang Hua; Jia Si Wang; Zhong Wei Chen; Song Yang Du', 2012, '<jats:p>This paper is to study the common architecture of the software development and compare the software system architecture-selection criteria. Meanwhile, this paper offers appropriate software architecture solution according to the features of data information management of the software testing organization.</jats:p>', '10.4028/www.scientific.net/amm.263-266.1745', 'https://doi.org/10.4028/www.scientific.net/amm.263-266.1745' WHERE NOT EXISTS (SELECT 1 FROM publications WHERE doi = '10.4028/www.scientific.net/amm.263-266.1745');
