INSERT INTO publications (title, authors, year, abstract_text, doi, url) SELECT 'Gem #85', 'Thomas Quinot', 2012, '<jats:p>Ada Gem #85 --- This is the second in a series of Gems introducing the facilities defined by the optional annex for Distributed Systems (Annex E) of the Ada Reference Manual. In the first installment, we showed how a simple client/server architecture can be implemented easily with the Distributed Systems Annex (DSA). We now introduce distributed objects, which allow dynamic relationships between components of a distributed application.</jats:p>', '10.1145/2148436.2148449', 'https://doi.org/10.1145/2148436.2148449' WHERE NOT EXISTS (SELECT 1 FROM publications WHERE doi = '10.1145/2148436.2148449');
