INSERT INTO publications (title, authors, year, abstract_text, doi, url) SELECT 'Reseach on Distributed Material Requirements Planning Based on Distributed Decision Support Systems', 'Yu Kui Sheng; Wan Lian Lan', 2011, '<jats:p>Distributed Material Requirements Planning is widely used in manufacture enterprise. The decentralized decisions of purchasing and warehousing can be coordinated by Distributed Decision Support Systems. Distributed Decision Support Systems can improve flexibility to make right decision instantly.</jats:p>', '10.4028/www.scientific.net/amr.219-220.1191', 'https://doi.org/10.4028/www.scientific.net/amr.219-220.1191' WHERE NOT EXISTS (SELECT 1 FROM publications WHERE doi = '10.4028/www.scientific.net/amr.219-220.1191');
