INSERT INTO publications (title, authors, year, abstract_text, doi, url) SELECT 'International Journal of Intelligent Data and Machine Learning', 'Vaibhav Tummalapalli', 2026, '<jats:p>Predictive modeling in the automotive industry often involves analyzing customer behavior to anticipate events such as vehicle purchases, service visits, or campaign responses. However, when working with imbalanced data—such as rare events like luxury vehicle purchases or high-ticket service upgrades—over-sampling techniques are commonly used. These techniques introduce bias into the sample, requiring adjustments to predicted probabilities to reflect the true population proportions. This paper explores the methodology of adjusting predicted probabilities using prior probabilities and demonstrates its application in automotive propensity models.</jats:p>', '10.55640/ijidml-v03i04-02', 'https://doi.org/10.55640/ijidml-v03i04-02' WHERE NOT EXISTS (SELECT 1 FROM publications WHERE doi = '10.55640/ijidml-v03i04-02');
