INSERT INTO publications (title, authors, year, abstract_text, doi, url) SELECT 'Reviews research on applying machine learning techniques to reduce false positives for network intrusion detection systems', 'Kavita Rajora; Nazar salih Abdulhussein', 2023, '<jats:p>High false positive rates impede the adoption of anomaly detection methods, which have promise for detecting novel cyber threats. Techniques reviewed include Extreme Learning Machine (ELM), Hidden Markov Models (HMM), situation awareness frameworks, ensemble methods, and feature selection algorithms when applied to contemporary benchmark datasets. Findings show combinations of ELM, HMMs, and ensemble classifiers can achieve reduced false positive rates. However, gaps still exist in research using current representative data.</jats:p>', '10.58496/bjml/2023/005', 'https://doi.org/10.58496/bjml/2023/005' WHERE NOT EXISTS (SELECT 1 FROM publications WHERE doi = '10.58496/bjml/2023/005');
