INSERT INTO publications (title, authors, year, abstract_text, doi, url) SELECT 'TRAINING A SINGLE MACHINE LEARNING AGENT USING REINFORCEMENT LEARNING AND IMITATION LEARNING METHODS IN UNITY ENVIRONMENT', 'Marat Urmanov; Madina Alimanova', 2020, '<jats:p>This paper provides a research of Unity plugin that helps to develop Machine Learning Agents within Unity engine environment. This work introduces training a single Machine Learning Agent using both Reinforcement Learning and Imitation Learning methods, comparing the results andeffectiveness</jats:p>', '10.47344/xp0v6x77', 'https://doi.org/10.47344/xp0v6x77' WHERE NOT EXISTS (SELECT 1 FROM publications WHERE doi = '10.47344/xp0v6x77');
