INSERT INTO publications (title, authors, year, abstract_text, doi, url) SELECT 'Fake Review Detection using Machine Learning', 'Gayathri M; Y.S.N Siva Teja; K.Ajay Sharma', 2023, '<jats:p>Online reviews have become increasingly important in the world of e-commerce, serving as a powerful tool to establish a business''s reputation and attract new customers. However, the rise of fake reviews has become a growing concern as they can skew the reputation of a business and deceive potential customers. As a result, detecting fake reviews has become a key area of research in recent years.</jats:p>', '10.36647/ciml/04.02.a002', 'https://doi.org/10.36647/ciml/04.02.a002' WHERE NOT EXISTS (SELECT 1 FROM publications WHERE doi = '10.36647/ciml/04.02.a002');
