INSERT INTO publications (title, authors, year, abstract_text, doi, url) SELECT 'Using Deep Learning Methods to Monitor Non-Observable States in a Building', 'Kristoffer Tangrand; Bernt Bremdal', 2020, '<jats:p>This paper presents results from ongoing research with a goal to use a combination of time series from non-intrusive soft sensors and deep recurrent neural networks to predict room usage at a university campus. Training data was created by collecting measurements from sensors measuring room CO2, humidity, temperature, light, motion and sound, while the labels was created manually by human inspection. Results include analyses of relationships between different sensor data sequences and recommendations for a prototype predictive model using deep recurrent neural networks.</jats:p>', '10.7557/18.5159', 'https://doi.org/10.7557/18.5159' WHERE NOT EXISTS (SELECT 1 FROM publications WHERE doi = '10.7557/18.5159');
