INSERT INTO publications (title, authors, year, abstract_text, doi, url) SELECT 'Deep Learning Based Knowledge Assessment Systems in Education', 'Iskandarova Ziyoda Abdumajidovna; Iskandarova Marjona Shuxrat qizi', 2026, '<jats:p>This study explores deep learning models for automated student knowledge assessment. Using data from 1,480 STEM students, ANN, CNN, LSTM, and a hybrid CNN-LSTM were evaluated. The hybrid model achieved highest accuracy (94.7%), outperforming baselines. Results highlight the effectiveness of combining temporal and static features for adaptive learning systems and early intervention,</jats:p>', '10.55640/ijdsml-06-01-03', 'https://doi.org/10.55640/ijdsml-06-01-03' WHERE NOT EXISTS (SELECT 1 FROM publications WHERE doi = '10.55640/ijdsml-06-01-03');
