INSERT INTO publications (title, authors, year, abstract_text, doi, url) SELECT 'Sentiment Classification of Hindi Language using Natural Language Processing Techniques', 'Dr. Meghna Jain', 2022, '<jats:p>This paper has presented Hybrid Approach for determination of sentimental phrase or words from Hindi text automatically through use of Hindi sentiment’s lexicon and classifying them into polarity i.e. Positive, Negative and Neutral.</jats:p>', '10.55529/jlls.26.7.10', 'https://doi.org/10.55529/jlls.26.7.10' WHERE NOT EXISTS (SELECT 1 FROM publications WHERE doi = '10.55529/jlls.26.7.10');
