INSERT INTO publications (title, authors, year, abstract_text, doi, url) SELECT 'On some applications of finite-state automata theory to natural language  processing', 'MEHRYAR MOHRI', 1996, '<jats:p>We describe new applications of the theory of automata to natural  language processing: the representation of very large scale dictionaries  and the indexation of natural language texts. They are based on new algorithms  that we introduce and describe in detail. In particular, we give pseudocodes  for the determinisation of string to string transducers, the deterministic  union of <jats:italic>p</jats:italic>-subsequential string to string transducers, and the  indexation by automata. We report on several experiments illustrating the  applications.</jats:p>', '10.1017/s135132499600126x', 'https://doi.org/10.1017/s135132499600126x' WHERE NOT EXISTS (SELECT 1 FROM publications WHERE doi = '10.1017/s135132499600126x');
