INSERT INTO publications (title, authors, year, abstract_text, doi, url) SELECT 'A survey of graphs in natural language processing', 'VIVI NASTASE; RADA MIHALCEA; DRAGOMIR R. RADEV', 2015, '<jats:title>Abstract</jats:title><jats:p>Graphs are a powerful representation formalism that can be applied to a variety of aspects related to language processing. We provide an overview of how Natural Language Processing problems have been projected into the graph framework, focusing in particular on graph construction – a crucial step in modeling the data to emphasize the phenomena targeted.</jats:p>', '10.1017/s1351324915000340', 'https://doi.org/10.1017/s1351324915000340' WHERE NOT EXISTS (SELECT 1 FROM publications WHERE doi = '10.1017/s1351324915000340');
