INSERT INTO publications (title, authors, year, abstract_text, doi, url) SELECT 'An Introduction to Natural Language Processing: the Main Problems', 'Veronica Dahl', 2018, '<jats:p>Natural Language Processing aims to give computers the power to automatically process human language sentences, mostly in written text form but also spoken, for various purposes. This sub-discipline of AI (Artificial Intelligence) is also known as Natural Language Understanding.</jats:p>', '10.17345/triangle1.65-78', 'https://doi.org/10.17345/triangle1.65-78' WHERE NOT EXISTS (SELECT 1 FROM publications WHERE doi = '10.17345/triangle1.65-78');
