INSERT INTO publications (title, authors, year, abstract_text, doi, url) SELECT 'Review of constraints on vision‐based gesture recognition for human–computer interaction', 'Biplab Ketan Chakraborty; Debajit Sarma; M.K. Bhuyan; Karl F MacDorman', 2018, '<jats:p>The ability of computers to recognise hand gestures visually is essential for progress in human–computer interaction. Gesture recognition has applications ranging from sign language to medical assistance to virtual reality. However, gesture recognition is extremely challenging not only because of its diverse contexts, multiple interpretations, and spatio‐temporal variations but also because of the complex non‐rigid properties of the hand. This study surveys major constraints on vision‐based gesture recognition occurring in detection and pre‐processing, representation and feature extraction, and recognition. Current challenges are explored in detail.</jats:p>', '10.1049/iet-cvi.2017.0052', 'https://doi.org/10.1049/iet-cvi.2017.0052' WHERE NOT EXISTS (SELECT 1 FROM publications WHERE doi = '10.1049/iet-cvi.2017.0052');
