INSERT INTO publications (title, authors, year, abstract_text, doi, url) SELECT 'Minor Planet Databases', 'L. Rykhlova; E. Bakanas', 2015, '<jats:title>Abstract</jats:title><jats:p>We cast a retrospective look at the mankind’s acquaintance with minor bodies of the Solar System, at the explosive growth in their discoveries resulting from the technological progress, and at gradual understanding of the danger to our very existence that some of them might actually pose. Then, we review current effort, of the astronomical community in general and of its Russian part in particular, to integrate our rapidly expanding knowledge of the potential Earth impactors and to make it readily available online.</jats:p>', '10.1515/astro-2017-0247', 'https://doi.org/10.1515/astro-2017-0247' WHERE NOT EXISTS (SELECT 1 FROM publications WHERE doi = '10.1515/astro-2017-0247');
