INSERT INTO publications (title, authors, year, abstract_text, doi, url) SELECT 'BRIF and Variant Databases', 'Raymond Dalgleish', 2011, '<jats:title>Abstract</jats:title><jats:p>Databases of sequence variation in human genes (LSDBs) are an important resource for biology and medicine. Currently, the measurement of importance is not as objective as it might be and the establishment of impact factors would be of benefit to those who curate LSDBs. Specific issues relating to such databases are discussed.</jats:p>', '10.1038/npre.2011.5586.1', 'https://doi.org/10.1038/npre.2011.5586.1' WHERE NOT EXISTS (SELECT 1 FROM publications WHERE doi = '10.1038/npre.2011.5586.1');
