INSERT INTO publications (title, authors, year, abstract_text, doi, url) SELECT 'Databases, Donors and Development', 'Paul McConnell', 1991, '<jats:p>Discusses how developing countries, representing the poorest 75 per cent of the world′s population, ensure that they too are able to benefit from this “Information Age”. Concentrates on a specific donor organisation, Canada′s International Development Research Centre (IRDC) dedicated to research designed and managed by the developing countries themselves in keeping with their own priorities and undertaken for their own benefit. Concludes that developing‐country information units must consolidate their operational base by convincing users and institutional administrators that their services are valuable and worth maintaining.</jats:p>', '10.1108/eum0000000002404', 'https://doi.org/10.1108/eum0000000002404' WHERE NOT EXISTS (SELECT 1 FROM publications WHERE doi = '10.1108/eum0000000002404');
