INSERT INTO publications (title, authors, year, abstract_text, doi, url) SELECT 'The preservation of databases', 'Kevin Ashley', 2004, '<jats:p>This article outlines past and present practice in the long‐term preservation of databases. It describes one typology of databases affecting preservation methods. It also covers some outstanding challenges to database preservation and gives pointers to further reading on database preservation activity around the world.</jats:p>', '10.1108/03055720410551075', 'https://doi.org/10.1108/03055720410551075' WHERE NOT EXISTS (SELECT 1 FROM publications WHERE doi = '10.1108/03055720410551075');
