INSERT INTO publications (title, authors, year, abstract_text, doi, url) SELECT 'Exploring traditional and advanced cloud computing architecture', 'Vedaiyan Ramchand', 2023, '<jats:p xml:lang="en">This paper explores the fundamental elements of cloud computing architecture, discussing the integration of cloud computing with Big Data, the use of homomorphic encryption, and remote sensing data in cloud architecture. It also examines advanced cloud architectures, such as Hypervisor Clustering architecture, Load Balanced Virtual Server Instances architecture, Zero Downtime architecture, and Resource Reservation architecture, emphasizing their role in enhancing availability and scalability. The paper concludes by showcasing the significance of cloud computing architecture in addressing modern computational and data management challenges.</jats:p>', '10.26634/jcc.10.1.19936', 'https://doi.org/10.26634/jcc.10.1.19936' WHERE NOT EXISTS (SELECT 1 FROM publications WHERE doi = '10.26634/jcc.10.1.19936');
