INSERT INTO publications (title, authors, year, abstract_text, doi, url) SELECT 'Youth Meeting Generative Artificial Intelligence: Young People’s Ways of Navigating with Generative-Artificial-Intelligence-Powered Tools and Systems', 'Yucong Lao', 2026, '<jats:p>Yucong Lao’s doctoral dissertation in the field of Information Studies, “Youth Meeting GenAI: Young people''s media and information literacy practices in the information ecosystem shaped by generative artificial intelligence”, was examined on December 19, 2025, at the University of Oulu’s Faculty of Humanities. Professor Denise Agosto (Rutgers University, USA) served as the opponent, with Professor Noora Hirvonen (University of Oulu) as the custodian. The dissertation is published in University of Oulu’s publication archive OuluREPO at https://urn.fi/URN:NBN:fi:oulu-202511196795.</jats:p>', '10.23978/inf.178425', 'https://doi.org/10.23978/inf.178425' WHERE NOT EXISTS (SELECT 1 FROM publications WHERE doi = '10.23978/inf.178425');
