INSERT INTO publications (title, authors, year, abstract_text, doi, url) SELECT 'Use of Artificial Intelligence Tools by Law Enforcement Services in Light of the Artificial Intelligence Act', 'Jakub Marciniak', 2025, '<jats:p>Celem artykułu jest wskazanie przestępstw, w przypadku których służby państwowe mogą korzystać z systemów zdalnej identyfikacji biometrycznej w czasie rzeczywistym w przestrzeni publicznej. Zostanie to uczynione przez analizę przesłanek umożliwiających posługiwanie się tą technologią oraz przyrównanie ich do czynów zabronionych przez polski kodeks karny. Rezultatem powyższego jest stworzenie katalogu przestępstw, odnośnie do których służby mogą zastosować system zdalnej identyfikacji biometrycznej w czasie rzeczywistym w przestrzeni publicznej. Ustalenia zawarte w tekście są bardzo istotne ze względu na obserwowany od kilku lat gwałtowny rozwój sztucznej inteligencji.</jats:p>', '10.14746/zpuam.2025.15.4', 'https://doi.org/10.14746/zpuam.2025.15.4' WHERE NOT EXISTS (SELECT 1 FROM publications WHERE doi = '10.14746/zpuam.2025.15.4');
