INSERT INTO publications (title, authors, year, abstract_text, doi, url) SELECT 'Introducing WIREs Data Mining and Knowledge Discovery', 'Witold Pedrycz', 2011, '<jats:title>Abstract</jats:title><jats:p>This article is categorized under: <jats:list list-type="explicit-label"> <jats:list-item><jats:p>Algorithmic Development &gt; Biological Data Mining</jats:p></jats:list-item> <jats:list-item><jats:p>Algorithmic Development &gt; Spatial and Temporal Data Mining</jats:p></jats:list-item> <jats:list-item><jats:p>Application Areas &gt; Health Care</jats:p></jats:list-item> <jats:list-item><jats:p>Technologies &gt; Structure Discovery and Clustering</jats:p></jats:list-item> </jats:list></jats:p>', '10.1002/widm.17', 'https://doi.org/10.1002/widm.17' WHERE NOT EXISTS (SELECT 1 FROM publications WHERE doi = '10.1002/widm.17');
