INSERT INTO publications (title, authors, year, abstract_text, doi, url) SELECT 'Child-Centered Evaluation: Broadening the Child/Designer Dyad', 'Sofia Pardo; Steve Howard; Frank Vetere', 2008, '<jats:p>Some settings challenge a literal interpretation of user-centered design orthodoxy; that design is best done<jats:italic>for</jats:italic>a user, by designing<jats:italic>with</jats:italic>that user. We explore the value that a copresent proxy and interpreter can bring to certain<?bhlt?>hard-to-reach<?ehlt?>or<?bhlt?>difficult-to-interpret<?ehlt?>situations; in this case the evaluation of educational software intended<?bhlt?>to be used<?ehlt?>by children. We discuss the effect that introducing a teacher had on the results of the evaluation and conclude that adding an expert-based component to evaluations increased its diagnostic power.</jats:p>', '10.1155/2008/597629', 'https://doi.org/10.1155/2008/597629' WHERE NOT EXISTS (SELECT 1 FROM publications WHERE doi = '10.1155/2008/597629');
