INSERT INTO publications (title, authors, year, abstract_text, doi, url) SELECT 'AI Resilience and Information Retrieval', 'Paul Kantor', 2025, '<jats:p>IR provides multiple versions and sources to confirm an assertion. AI provides (essentially statistical) compilation and weighting of all those inputs. And generates a coherent and syntactically appropriate statement. What could go wrong?</jats:p>', '10.54195/irrj.25004', 'https://doi.org/10.54195/irrj.25004' WHERE NOT EXISTS (SELECT 1 FROM publications WHERE doi = '10.54195/irrj.25004');
