INSERT INTO publications (title, authors, year, abstract_text, doi, url) SELECT 'Information Retrieval for E-Discovery', 'Douglas W. Oard; William Webber', 2013, '<jats:p>E-discovery refers generally to the process by which one party (for example, the plaintiff) is entitled to “discover” evidence in the form of “electronically stored information” that is held by another party (for example, the defendant), and that is relevant to some matter that is the subject of civil litigation (that is, what is commonly called a “lawsuit”). This survey describes the emergence of the field, identifies the information retrieval issues that arise, reviews the work to date on this topic, and summarizes major open issues.</jats:p>', '10.1561/1500000025', 'https://doi.org/10.1561/1500000025' WHERE NOT EXISTS (SELECT 1 FROM publications WHERE doi = '10.1561/1500000025');
