INSERT INTO publications (title, authors, year, abstract_text, doi, url) SELECT 'The interface between computerized retrieval systems and micrographic retrieval systems', 'George McMurdo', 1979, '<jats:p>This paper notes the benefits accruing from interaction between computerized retrieval systems and micrographic retrieval systems. It reviews current state of automated micrographic retrieval technology. The conclusion is that with a combination of advances in communications technol ogy, and sophisticated indexing input from librarians and information scientists, the new generation of automated micrographs devices may constitute the on-line document retrieval systems of the future.</jats:p>', '10.1177/016555157900100605', 'https://doi.org/10.1177/016555157900100605' WHERE NOT EXISTS (SELECT 1 FROM publications WHERE doi = '10.1177/016555157900100605');
