INSERT INTO publications (title, authors, year, abstract_text, doi, url) SELECT 'Why software engineering programs should teach agile software development', 'Orit Hazzan; Yael Dubinsky', 2007, '<jats:p>In this paper we propose ten reasons why it is important, suitable and timely to introduce agile software development into software engineering programs in the academia. These reasons address technical, social and cognitive issues.</jats:p>', '10.1145/1234741.1234758', 'https://doi.org/10.1145/1234741.1234758' WHERE NOT EXISTS (SELECT 1 FROM publications WHERE doi = '10.1145/1234741.1234758');
