INSERT INTO publications (title, authors, year, abstract_text, doi, url) SELECT 'SOFTWARE METRICS IN SOFTWARE ENGINEERING AND ARTIFICIAL INTELLIGENCE', 'MARTIN J. SHEPPERD; DARREL C. INCE', 1991, '<jats:p> This paper examines the utility of much of the software metrics research that has been carried out in software engineering to problems in artificial intelligence. The paper first reviews the work that has been carried out and then makes a number of suggestions about how it could be transferred to the artificial intelligence arena — applying it in particular to expert system development. </jats:p>', '10.1142/s0218194091000305', 'https://doi.org/10.1142/s0218194091000305' WHERE NOT EXISTS (SELECT 1 FROM publications WHERE doi = '10.1142/s0218194091000305');
