INSERT INTO publications (title, authors, year, abstract_text, doi, url) SELECT 'Surfing the net for software engineering notes', 'Mark Doernhoefer', 2007, '<jats:p>             The subtitle to this month''s article is just meant to grab your attention. I assure you, this column will             <jats:bold>not</jats:bold>             be solving the software quality problem. What I do hope to do is point you at some interesting web sites that discuss potential solutions to the software quality problem and let you solve it on your own.           </jats:p>', '10.1145/1234741.1234745', 'https://doi.org/10.1145/1234741.1234745' WHERE NOT EXISTS (SELECT 1 FROM publications WHERE doi = '10.1145/1234741.1234745');
