INSERT INTO publications (title, authors, year, abstract_text, doi, url) SELECT 'Software Security Engineering', 'Khaled M. Khan', 2012, '<jats:p>Muthu Ramachandran from Leeds Metropolitan University, UK has recently published a book entitled, Software Security Engineering: Design and Applications. The author claims that the book provides systematic approaches to engineering, building and assuring software security throughout software lifecycle, software security based requirements engineering, design for software security, software security implementation, best practice guideline on developing software security, test for software security, and quality validation for software security.</jats:p>', '10.4018/jsse.2012010104', 'https://doi.org/10.4018/jsse.2012010104' WHERE NOT EXISTS (SELECT 1 FROM publications WHERE doi = '10.4018/jsse.2012010104');
