INSERT INTO publications (title, authors, year, abstract_text, doi, url) SELECT 'Real-life software projects as Software Engineering Laboratory exercises', 'Kyu Y. Lee; Eric C. Frankel', 1983, '<jats:p>The Software Engineering Laboratory is a one-academic-year course required for the Master of Software Engineering degree at Seattle University. It is designed to simulate a real-life software development project environment, providing equal focus on technical and managerial considerations. The output of the laboratory must be a software product of marketable quality.This paper describes the experience gained from the laboratory projects and discusses directions for future projects.</jats:p>', '10.1145/1010891.1010896', 'https://doi.org/10.1145/1010891.1010896' WHERE NOT EXISTS (SELECT 1 FROM publications WHERE doi = '10.1145/1010891.1010896');
