INSERT INTO publications (title, authors, year, abstract_text, doi, url) SELECT 'The role of software configuration management in a measurement-based software engineering program', 'Kristopher G. Sprague', 1991, '<jats:p>The role of Software Configuration Management has rapidly expanded and grown in importance over the last few years for a number of reasons. This paper presents an overview of the significant changes that are occurring in the Software Configuration Management discipline with respect to its role in a measurement-based software engineering program. It identifies the changes, provides an overview of the SCM functions, proposes a process, and discusses directions for future research and development.</jats:p>', '10.1145/122538.122547', 'https://doi.org/10.1145/122538.122547' WHERE NOT EXISTS (SELECT 1 FROM publications WHERE doi = '10.1145/122538.122547');
