INSERT INTO publications (title, authors, year, abstract_text, doi, url) SELECT 'VIMAR: vision-language informed malware analysis and reasoning model', 'Shiting Xu', 2026, '<jats:title>Abstract</jats:title>                   <jats:p>Malware family classification is crucial for threat detection, yet existing methods struggle with generalization, multi-task adaptability, and interpretability. We propose VIMAR, a unified vision–language model that supports classification, similarity detection, and open-world analysis via explanation-rich supervision and a two-stage training pipeline. On the Malimg dataset, VIMAR achieves 94.2% accuracy in family classification, surpassing the best CNN baseline by +3.1%. It also attains 85.2% and 88.0% accuracy in zero-shot and few-shot settings, significantly outperforming vision–language baselines. Moreover, its reasoning outputs align well with human judgments. The codebase and scripts will be released to the community.</jats:p>', '10.1186/s42400-025-00481-3', 'https://doi.org/10.1186/s42400-025-00481-3' WHERE NOT EXISTS (SELECT 1 FROM publications WHERE doi = '10.1186/s42400-025-00481-3');
