INSERT INTO publications (title, authors, year, abstract_text, doi, url) SELECT 'Introduction to the Special Issue on LLM Empowered Internet of Things Part 2', 'Wei Dong; Jiliang Wang; Stephan Sigg; Luca Mottola', 2026, '<jats:p>ACM TIOT launched a special issue on the theme of LLM Empowered Internet of Things, exploring the intersection of Large Language Models (LLMs) and the Internet of Things (IoT). As IoT continues to expand, advanced computational models are increasingly essential for processing and analyzing the massive data generated by interconnected devices. This special issue focuses on how LLMs can enhance IoT systems in several key areas. The second part of this special issue introduces the remaining six accepted papers that spans a board range of IoT scenarios from embedded and cyber-physical systems, human-centered applications, to IoT security.</jats:p>', '10.1145/3798286', 'https://doi.org/10.1145/3798286' WHERE NOT EXISTS (SELECT 1 FROM publications WHERE doi = '10.1145/3798286');
