INSERT INTO publications (title, authors, year, abstract_text, doi, url) SELECT 'Retraction of published article due to the author’s proposal', 'Tetiana Vakaliuk', 2023, '<jats:p>Based according to the author''s proposal, the editorial board of the Journal of Edge Computing withdraws the paper:Sverdlova, A.D., Zaporozhets, A.O., Bohachev, I.V., Popov, O.O., Iatsyshyn, A.V., Iatsyshyn, A.V., Kovach, V.O., Artemchuk, V.O. and Hrushchynska, N.M., 2022. Dynamic routing protocols for wireless touch networks: a review. Journal of Edge Computing, 1(1), pp.29–42. Available from: https://doi.org/10.55056/jec.571.    </jats:p>', '10.55056/jec.575', 'https://doi.org/10.55056/jec.575' WHERE NOT EXISTS (SELECT 1 FROM publications WHERE doi = '10.55056/jec.575');
