INSERT INTO publications (title, authors, year, abstract_text, doi, url) SELECT 'Autonomous AI Systems for Edge Computing and IoT Environments: Enhancing Intelligence at the Edge', 'Venkateswara rao batta', 2025, '<jats:p>Edge AI is revolutionizing the Internet of Things (IoT) by enabling real-time decision-making and autonomous operations. This paper explores the design and deployment of autonomous AI systems optimized for edge computing environments. The proposed architecture integrates lightweight AI models with advanced edge hardware to deliver high performance, low latency, and energy efficiency. Applications in smart cities, industrial automation, and autonomous vehicles are analyzed, demonstrating significant improvements in responsiveness, reliability, and operational scalability. The study provides insights into the future of autonomous systems and their potential to drive IoT innovation.</jats:p>', '10.69889/r489hj77', 'https://doi.org/10.69889/r489hj77' WHERE NOT EXISTS (SELECT 1 FROM publications WHERE doi = '10.69889/r489hj77');
