INSERT INTO publications (title, authors, year, abstract_text, doi, url) SELECT 'Pre-DNNOff: On-Demand DNN Model Offloading Method for Mobile Edge Computing', 'Lin Zuo', 2024, '<jats:p>Deep Neural Networks (DNNs) are critical for modern intelligent processing but cause significant latency and energy consumption issues on mobile devices due to their high computational demands. Moreover, different tasks have different accuracy demands for DNN inference. To balance latency and accuracy across various tasks, we introduce PreDNNOff, a method that offloads DNNs at a layer granularity within the Mobile Edge Computing (MEC) environment. PreDNNOff utilizes a binary stochastic programming model and Genetic Algorithms (GAs) to optimize the expected latency for multiple exit points based on the distribution of task inference accuracy and layer latency regression models. Compared to the existing method Edgent, PreDNNOff has achieved a reduction of about 10% in the expected total latency, and due to the consideration of different tasks’ varying requirements for accuracy, it has a broader applicability.</jats:p>', '10.12694/scpe.v25i6.3393', 'https://doi.org/10.12694/scpe.v25i6.3393' WHERE NOT EXISTS (SELECT 1 FROM publications WHERE doi = '10.12694/scpe.v25i6.3393');
INSERT INTO tags (name) SELECT 'Edge Computing' WHERE NOT EXISTS (SELECT 1 FROM tags WHERE name = 'Edge Computing');
