INSERT INTO publications (title, authors, year, abstract_text, doi, url) SELECT 'The Essence of Quantum Computing', 'Rajendra K. Bera', 2018, '<jats:p>In Part I we laid the foundation on which quantum algorithms are built. In this part we harness such exotic aspects as superposition, entanglement and collapse of quantum states of that foundation to show how powerful quantum algorithms can be constructed for efficient computation. Appendixes A and B are provided to jog the memory of those who are recently out of touch with linear algebra and Fourier series.</jats:p>', '10.34048/2018.2.f1', 'https://doi.org/10.34048/2018.2.f1' WHERE NOT EXISTS (SELECT 1 FROM publications WHERE doi = '10.34048/2018.2.f1');
