INSERT INTO publications (title, authors, year, abstract_text, doi, url) SELECT 'qprof: A gprof-Inspired Quantum Profiler', 'Adrien Suau; Gabriel Staffelbach; Aida Todri-Sanial', 2023, '<jats:p>We introduce qprof, a new and extensible quantum program profiler able to generate profiling reports of quantum circuits written using various quantum computing frameworks. We describe the internal structure and working of qprof and provide practical examples on quantum circuits with increasing complexity along with benchmarks of the tool execution time on large circuits. This tool will allow researchers to visualise their quantum algorithm implementation in a different and complementary way and reliably localise the bottlenecks for efficient code optimisation.</jats:p>', '10.1145/3529398', 'https://doi.org/10.1145/3529398' WHERE NOT EXISTS (SELECT 1 FROM publications WHERE doi = '10.1145/3529398');
