INSERT INTO publications (title, authors, year, abstract_text, doi, url) SELECT 'Robot Skill Learning: From Reinforcement Learning to Evolution Strategies', 'Freek Stulp; Olivier Sigaud', 2013, '<jats:title>Abstract</jats:title><jats:p>Policy improvement methods seek to optimize the parameters of a policy with respect to a utility function. Owing to current trends involving searching in parameter space (rather than action space) and using reward-weighted averaging (rather than gradient estimation), reinforcement learning algorithms for policy improvement, e.g. PoWER and PI</jats:p>', '10.2478/pjbr-2013-0003', 'https://doi.org/10.2478/pjbr-2013-0003' WHERE NOT EXISTS (SELECT 1 FROM publications WHERE doi = '10.2478/pjbr-2013-0003');
