INSERT INTO publications (title, authors, year, abstract_text, doi, url) SELECT 'Can Big Data Machines Analyze Stock Market Sentiment?', 'Vasant Dhar', 2014, '<jats:title>Abstract</jats:title>                   <jats:p>Do the massive amounts of social and professionally curated data on the Internet contain useful sentiment about the market that “big data machines” can extract systematically? If so, what are the important challenges in creating economic value from these diffuse sources? In this commentary, I delve into these questions and frame the challenges involved using recent market developments as an illustrative backdrop.</jats:p>', '10.1089/big.2014.1528', 'https://doi.org/10.1089/big.2014.1528' WHERE NOT EXISTS (SELECT 1 FROM publications WHERE doi = '10.1089/big.2014.1528');
INSERT INTO tags (name) SELECT 'Big Data' WHERE NOT EXISTS (SELECT 1 FROM tags WHERE name = 'Big Data');
INSERT INTO publication_tags (publication_id, tag_id) SELECT p.id, t.id FROM publications p JOIN tags t ON t.name = 'Big Data' WHERE p.doi = '10.1089/big.2014.1528' AND NOT EXISTS (SELECT 1 FROM publication_tags pt WHERE pt.publication_id = p.id AND pt.tag_id = t.id);
INSERT INTO publications (title, authors, year, abstract_text, doi, url) SELECT 'Big Data and Predictive Analytics in Health Care', 'Vasant Dhar', 2014, '<jats:title>Abstract</jats:title>                   <jats:p>Predictive analytics show great promise in health care but face some serious hurdles for widespread adoption. I discuss the state of the art of predictive health-care analytics using the clinical arena as an example and discuss how the outputs of predictive systems could be made actionable through differentiated processes that encourage prevention. Such systems have the potential to minimize health risk at the population and individual levels through more personalized health-care delivery.</jats:p>', '10.1089/big.2014.1525', 'https://doi.org/10.1089/big.2014.1525' WHERE NOT EXISTS (SELECT 1 FROM publications WHERE doi = '10.1089/big.2014.1525');
INSERT INTO tags (name) SELECT 'Big Data' WHERE NOT EXISTS (SELECT 1 FROM tags WHERE name = 'Big Data');
