INSERT INTO publications (title, authors, year, abstract_text, doi, url) SELECT 'Big Data and Small: Collaborations between ethnographers and data scientists', 'Heather Ford', 2014, '<jats:p>In the past three years, Heather Ford—an ethnographer and now a PhD student—has worked on ad hoc collaborative projects around Wikipedia sources with two data scientists from Minnesota, Dave Musicant and Shilad Sen. In this essay, she talks about how the three met, how they worked together, and what they gained from the experience. Three themes became apparent through their collaboration: that data scientists and ethnographers have much in common, that their skills are complementary, and that discovering the data together rather than compartmentalizing research activities was key to their success.</jats:p>', '10.1177/2053951714544337', 'https://doi.org/10.1177/2053951714544337' WHERE NOT EXISTS (SELECT 1 FROM publications WHERE doi = '10.1177/2053951714544337');
