INSERT INTO publications (title, authors, year, abstract_text, doi, url) SELECT 'Labor Economists Get Their Microscope: Big Data and Labor Market Analysis', 'John J. Horton; Prasanna Tambe', 2015, '<jats:title>Abstract</jats:title>                   <jats:p>This article describes how the fine-grained data being collected by Internet labor market intermediaries, such as employment websites, online labor markets, and knowledge discussion boards, are providing new research opportunities and directions for the empirical analysis of labor market activity. After discussing these data sources, we examine some of the research opportunities they have created, highlight some examples of existing work that already use these new data sources, and enumerate the challenges associated with the use of these corporate data sources.</jats:p>', '10.1089/big.2015.0017', 'https://doi.org/10.1089/big.2015.0017' WHERE NOT EXISTS (SELECT 1 FROM publications WHERE doi = '10.1089/big.2015.0017');
