INSERT INTO publications (title, authors, year, abstract_text, doi, url) SELECT 'Big Data and Consumer Behavior: Analyzing Shopping Patterns', 'Emily Roberts', 2025, '<jats:p>In recent years, Big Data analytics has become an essential tool for understanding consumer behavior. By analyzing vast amounts of data generated by consumers, businesses can gain valuable insights into shopping patterns, preferences, and purchasing decisions. This article explores how Big Data technologies can be used to analyze consumer behavior, identify trends, predict future purchasing behaviors, and optimize marketing strategies. Through examining the role of consumer data from online transactions, social media interactions, and mobile applications, businesses can gain a better understanding of their customers and enhance their marketing efforts.</jats:p>', '10.71465/ajbd3523', 'https://doi.org/10.71465/ajbd3523' WHERE NOT EXISTS (SELECT 1 FROM publications WHERE doi = '10.71465/ajbd3523');
