INSERT INTO publications (title, authors, year, abstract_text, doi, url) SELECT 'The Use of Big Data for Improving Urban Mobility', 'Dr. Jessica Stevens', 2023, '<jats:p>Urban mobility has become a critical issue for cities around the world due to population growth, congestion, and environmental concerns. Big data has the potential to revolutionize urban transportation systems by providing real-time insights into traffic patterns, public transit usage, and mobility trends. This article explores how big data is being used to improve urban mobility, with a focus on transportation planning, congestion management, and the integration of different modes of transport.</jats:p>', '10.71465/ajbd752', 'https://doi.org/10.71465/ajbd752' WHERE NOT EXISTS (SELECT 1 FROM publications WHERE doi = '10.71465/ajbd752');
